{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목에 근거해 개선 방법을 선택한 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "운영 화면의 신고 목록 조회 쿼리에서 응답 지연이 발생한 상황",
          "task": "조회 지연의 원인에 맞는 쿼리 개선 방법 선택",
          "action": "실행 계획에서 확인한 병목과 조회 조건을 근거로 인덱스 추가나 조인 수정 등 개선 방법을 선택한 기준 설명",
          "result": "개선 전후 응답 시간의 측정 조건과 수치 변화는 꼬리질문에서 확인"
        },
        "expectedEvidence": [
          "실행 계획에서 확인한 조회 범위나 조인 처리 특성이 개선 방법의 선택 근거로 제시됨",
          "선택한 개선 방법이 해당 병목을 줄이는 데 적합하다고 판단한 기준이 제시됨"
        ]
      },
      "question": "운영 화면의 신고 목록 조회 쿼리를 개선하셨다고 했는데요. 쿼리 개선 방법은 어떤 기준으로 정하셨나요?",
      "answerTip": "당시 경험을 떠올리며 질문받은 내용에 집중해 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 확인한 조회 범위나 조인 처리의 구체적인 특성을 개선 방법의 선택 근거로 설명한다.",
            "인덱스 추가나 조인 수정 등 선택한 방법이 확인된 병목을 줄이는 이유를 조회 조건이나 처리 구조와 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "조회 비용을 줄이려는 선택 기준은 제시하지만 실행 계획에서 확인한 병목의 설명이 부족하다.",
            "개선 방법을 선택한 이유는 설명하지만 해당 쿼리의 조회 조건이나 조인 구조와의 연결이 약하다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스를 추가하거나 쿼리를 수정했다는 작업만 나열하고 선택 기준을 설명하지 못한다.",
            "응답 시간이 줄었다는 결과나 일반적인 최적화 지식만 말하고 해당 쿼리의 병목과 연결하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 오류에서 당장의 복구 조치와 재발 방지 조치를 구분해 세운 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "배포 후 알림 중복 발송 오류가 발생한 상황",
          "task": "오류의 영향을 멈추기 위한 복구 조치와 같은 장애를 막기 위한 재발 방지 조치를 구분",
          "action": "로그로 확인한 발생 원인과 반복 조건에 비추어 각 조치의 목적을 구분한 기준 설명",
          "result": "복구 여부와 재발 방지 조치의 실제 적용 결과는 꼬리질문에서 확인"
        },
        "expectedEvidence": [
          "진행 중인 오류의 영향을 멈추는 목적과 이후 같은 오류의 발생 조건을 차단하는 목적을 구분한 기준",
          "로그로 파악한 오류 원인이나 반복 조건을 복구·재발 방지 조치의 구분에 연결한 설명"
        ]
      },
      "question": "배포 후 알림 중복 발송 오류를 수정하셨다고 했는데요. 당장 복구할 조치와 재발을 막을 조치는 어떤 기준으로 나누셨나요?",
      "answerTip": "당시 상황을 떠올리며 본인이 판단한 내용을 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진행 중인 중복 발송을 멈추는 목적과 이후 같은 장애의 발생 조건을 차단하는 목적을 기준으로 조치를 구분한다.",
            "로그에서 파악한 오류 원인이나 반복 조건을 들어 각 조치를 복구 또는 재발 방지로 구분한 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "즉시 복구와 재발 방지의 목적 차이는 설명하지만 실제 조치를 나눈 기준이 추상적이다.",
            "조치의 구분 기준은 제시하지만 로그로 파악한 원인이나 반복 조건과의 연결이 약하다."
          ]
        },
        "poor": {
          "criteria": [
            "수행한 수정 작업만 나열하고 복구와 재발 방지 조치를 나눈 기준을 설명하지 못한다.",
            "오류 원인을 찾은 이야기만 하거나 두 조치의 목적을 구분하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "요청의 목적과 범위를 개발·디자인 담당자와 합의할 수 있는 요구사항 정의서로 구체화한 순서를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 인터뷰로 수집한 요청을 요구사항으로 정리하던 상황",
          "task": "포함·제외 범위, 우선순위와 예외 케이스가 드러나는 요구사항 정의서 작성",
          "action": "요청의 목적 정리, 포함·제외 범위와 우선순위 결정, 예외 케이스 명세, 담당자와의 범위 확인을 문서화 순서에 연결해 설명",
          "result": "문서를 통한 범위 합의 여부는 꼬리질문에서 확인"
        },
        "expectedEvidence": [
          "수집한 요청의 목적을 정리하고 요구사항의 포함·제외 범위를 문서화한 순서",
          "우선순위와 예외 케이스를 요구사항 정의서에 구체화한 단계",
          "개발·디자인 담당자와 범위를 확인하는 단계를 문서 작성 순서에 배치한 설명"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 요구사항 정의서를 작성하셨다고 했는데요. 어떤 순서로 요구사항 정의서를 구체화하셨나요?",
      "answerTip": "당시 작업을 떠올리며 본인이 했던 일을 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 요청을 예로 들어 목적 정리에서 포함·제외 범위 명세로 이어지는 작성 순서를 설명한다.",
            "우선순위와 예외 케이스를 문서에 구체화한 단계가 드러난다.",
            "담당자와 범위를 확인하는 단계가 문서 작성 순서에서 어디에 있었는지 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요청을 요구사항 정의서로 옮긴 순서는 설명하지만, 목적과 포함·제외 범위를 구체화한 단계가 불명확하다.",
            "우선순위, 예외 케이스 또는 범위 확인 단계의 설명이 일부 빠지거나 실제 작성 내용과의 연결이 약하다."
          ]
        },
        "poor": {
          "criteria": [
            "인터뷰나 요청 수집 이야기만 하고 요구사항 정의서로 구체화한 순서를 설명하지 못한다.",
            "문서의 형식이나 사용 도구만 설명하고 범위, 우선순위, 예외 케이스를 명세한 단계는 제시하지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기능 흐름을 화면별 동작과 상태, 예외 상황, 안내 문구가 드러나는 스토리보드로 구체화한 순서를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 화면설계서를 작성하던 상황",
          "task": "개발자와 디자이너가 구현할 수 있도록 화면별 동작을 스토리보드에 명세",
          "action": "기능 흐름을 화면 단위로 나누고 상태 변화, 예외 상황과 안내 문구를 구체화한 순서를 실제 화면을 바탕으로 설명",
          "result": "구현 중 추가 확인이 필요했는지는 꼬리질문에서 확인"
        },
        "expectedEvidence": [
          "기능 흐름을 화면 단위와 화면 간 이동으로 구체화한 순서",
          "화면별 상태 변화와 예외 상황의 동작을 명세한 단계",
          "각 상태와 예외 상황에 필요한 안내 문구를 스토리보드에 배치한 단계"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서를 작성하셨다고 했는데요. 어떤 순서로 화면별 동작을 스토리보드에 구체화하셨나요?",
      "answerTip": "기억에 남는 작업 장면을 떠올리며 편하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 화면을 예로 들어 기능 흐름을 화면 단위와 화면 간 이동으로 풀어낸 순서를 설명한다.",
            "상태 변화와 예외 상황의 동작을 어느 단계에서 명세했는지 설명한다.",
            "상태와 예외 상황에 따른 안내 문구를 스토리보드에 구체화한 단계가 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "화면별 동작을 스토리보드로 작성한 순서는 설명하지만 실제 화면과의 연결이 약하다.",
            "기본 흐름을 명세한 단계는 드러나지만 상태 변화, 예외 상황 또는 안내 문구를 구체화한 단계의 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "도구 사용법이나 화면의 시각적 배치만 설명하고 화면별 동작을 명세한 순서는 제시하지 않는다.",
            "기능 목록만 나열하고 화면 흐름, 상태 변화와 예외 상황을 스토리보드로 구체화한 단계를 설명하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "진통제 투약 절차의 수행 순서를 통해 환자와 처방 내용을 확인하고, 확인되지 않은 처방은 투약을 멈춰 담당자에게 확인하는지 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 투약 중 처방 확인이 필요했던 상황",
          "task": "확인 절차에 따라 처방의 적절성을 확인한 뒤 안전하게 투약하기",
          "action": "환자 확인과 약물·용량·경로·시간 확인 순서를 설명하고, 의심되는 처방은 투약을 중단한 상태에서 담당자에게 확인하는 절차를 제시한다.",
          "result": "처방 확인 이후의 투약 여부와 처리 결과는 꼬리질문에서 확인한다."
        },
        "expectedEvidence": [
          "투약 전에 처방 대상과 실제 환자가 일치하는지 확인하는 단계가 제시된다.",
          "약물·용량·경로·시간을 처방과 확인하는 단계가 투약보다 앞에 배치된다.",
          "처방이 의심스럽거나 확인되지 않으면 투약을 멈추고 담당자에게 확인한 뒤 진행 여부를 정하는 순서가 드러난다."
        ]
      },
      "question": "수술 후 환자의 진통제 투약을 멈추셨다고 했는데요. 당시 진통제 투약 절차는 어떤 순서로 진행하셨나요?",
      "answerTip": "당시 장면을 떠올리며 본인이 한 일을 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "당시 수행한 절차를 바탕으로 환자 확인과 약물·용량·경로·시간 확인이 투약에 앞서 이루어졌음을 순서대로 설명한다.",
            "의심되는 처방을 확인하기 전에는 투약하지 않고 담당자 확인을 거쳐 진행 여부를 정하는 순서가 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "투약 전 확인과 의심 처방의 중단·확인 순서는 설명하지만, 환자 확인이나 약물·용량·경로·시간 중 일부 확인 단계가 불분명하다.",
            "안전한 투약 순서를 제시하지만 당시 실제로 수행한 절차와의 연결이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "투약 전 확인 순서를 설명하지 못하거나 주의해서 투약한다는 일반적인 다짐에 그친다.",
            "처방이 의심스럽거나 확인되지 않은 상태에서도 먼저 투약한 뒤 확인하는 순서를 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태 변화를 간호 기록에 남기는 기준을 통해 관찰한 변화가 정확히 드러나도록 기록할 수 있는지 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "활력징후와 통증을 관찰하면서 환자 상태 변화를 기록했던 상황",
          "task": "정해진 관찰 주기에 따라 확인한 환자 상태 변화를 간호 기록에 정확히 남기기",
          "action": "관찰 시점, 실제 측정값과 환자 호소, 이전 상태와의 차이를 바탕으로 상태 변화를 기록하는 기준을 설명한다.",
          "result": "기록한 내용이 의사 보고와 다음 근무자 인수인계로 이어졌는지는 꼬리질문에서 확인한다."
        },
